#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""x402 付费接口骨架：先验后付、成功才结算、nonce 防重放。"""
import base64, json, sqlite3, time, urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

FACILITATOR = "https://x402.org/facilitator"
PAY_TO = "0xYourAddress"
ASSET = "0x036CbD53842c5426634e7929541eC2318f3dCF7e"  # base-sepolia USDC
NETWORK = "base-sepolia"
PRICE = "1000"  # micro-USDC

db = sqlite3.connect("paid.db", check_same_thread=False)
db.execute("CREATE TABLE IF NOT EXISTS seen(nonce TEXT PRIMARY KEY, tx TEXT, ts INT)")
db.commit()

req = {
    "x402Version": 1, "scheme": "exact", "network": NETWORK,
    "maxAmountRequired": PRICE, "resource": "http://localhost:8400/paid",
    "description": "paid endpoint", "mimeType": "application/json",
    "payTo": PAY_TO, "maxTimeoutSeconds": 120, "asset": ASSET,
    "extra": {"name": "USDC", "version": "2"},
}


def post(path, body):
    data = json.dumps(body).encode()
    r = urllib.request.Request(FACILITATOR + path, data=data,
                              headers={"Content-Type": "application/json"})
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with opener.open(r, timeout=20) as resp:
        return json.loads(resp.read().decode())


def business_logic(payload):
    return {"echo": payload, "server_time": int(time.time())}


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _json(self, obj, code=200, extra=None):
        b = json.dumps(obj, ensure_ascii=False).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(b)))
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(b)

    def do_POST(self):
        n = int(self.headers.get("Content-Length") or 0)
        body = json.loads(self.rfile.read(n) or b"{}")
        hdr = self.headers.get("X-PAYMENT")
        if not hdr:
            return self._json({"x402Version": 1, "accepts": [req],
                               "error": "payment required"}, 402)
        pay = json.loads(base64.urlsafe_b64decode(hdr + "=" * (-len(hdr) % 4)))

        # 1) 本地只校结构，绝不放行
        auth = (pay.get("payload") or {}).get("authorization") or {}
        if int(auth.get("value") or 0) < int(PRICE):
            return self._json({"error": "amount_too_low"}, 402)
        nonce = str(auth.get("nonce") or "")
        if not nonce:
            return self._json({"error": "missing_nonce"}, 400)
        if db.execute("SELECT 1 FROM seen WHERE nonce=?", (nonce,)).fetchone():
            return self._json({"error": "nonce_replayed"}, 409)

        # 2) facilitator 判真伪
        v = post("/verify", {"x402Version": 1, "paymentPayload": pay,
                             "paymentRequirements": req})
        if not v.get("isValid"):
            return self._json({"error": "invalid_payment", "detail": v}, 402)

        # 3) 业务成功才 settle —— 别先收钱再干活
        try:
            result = business_logic(body)
        except Exception as e:
            return self._json({"error": "upstream_failed", "detail": str(e)}, 502)

        s = post("/settle", {"x402Version": 1, "paymentPayload": pay,
                             "paymentRequirements": req})
        if not s.get("success") or not s.get("transaction"):
            return self._json({"error": "settle_failed", "detail": s}, 502)

        db.execute("INSERT INTO seen(nonce,tx,ts) VALUES(?,?,?)",
                   (nonce, s["transaction"], int(time.time())))
        db.commit()
        receipt = base64.urlsafe_b64encode(json.dumps(s).encode()).decode().rstrip("=")
        return self._json(result, 200, {"X-PAYMENT-RESPONSE": receipt})


if __name__ == "__main__":
    ThreadingHTTPServer(("0.0.0.0", 8400), H).serve_forever()
